// Extraer y normalizar los datos recibidos del juego
const data = $json.body || $json;

const playerName = (data.playerName || 'Jugador Anónimo').trim();
const score = Number(data.score || 0);
const tier = Number(data.tier || 1);
const crownName = data.crownName || (tier === 3 ? 'Corona de Oro Real' : tier === 2 ? 'Corona de Plata' : 'Corona de Bronce');
const applesEaten = Number(data.applesEaten || Math.floor(score / 10));
const dateUnlocked = new Date().toISOString();

// Definir metadata del logro y recompensas de corona
const crownMetadata = {
  1: {
    title: '🥉 Rango Veterano — Corona de Bronce',
    requirement: 800,
    colorHex: '#cd7f32',
    colorDec: 13467442,
    badge: '👑🥉',
    perk: 'Maestría básica en reflejos',
    trophyId: 'TROPHY_BRONZE_800'
  },
  2: {
    title: '🥈 Rango Élite — Corona de Plata',
    requirement: 1600,
    colorHex: '#e2e8f0',
    colorDec: 14870768,
    badge: '👑🥈',
    perk: 'Velocidad y control hipersónico',
    trophyId: 'TROPHY_SILVER_1600'
  },
  3: {
    title: '👑🥇 Rango Supremo — Corona de Oro Real',
    requirement: 3500,
    colorHex: '#fbbf24',
    colorDec: 16498468,
    badge: '👑✨',
    perk: 'Inmortalidad y Gloria en la Tabla',
    trophyId: 'TROPHY_GOLD_3500'
  }
};

const meta = crownMetadata[tier] || crownMetadata[1];

// Generar payload compatible con Discord Webhooks
const discordEmbed = {
  username: 'Snake Game Bot 🐍',
  avatar_url: 'https://cdn-icons-png.flaticon.com/512/528/528098.png',
  embeds: [
    {
      title: `¡${playerName} ha desbloqueado la ${crownName}! ${meta.badge}`,
      description: `¡Hito histórico en **Snake Game**! El jugador superó la marca requerida logrando un desempeño legendario.`,
      color: meta.colorDec,
      fields: [
        { name: '👤 Jugador', value: playerName, inline: true },
        { name: '⭐ Puntuación', value: `${score} pts`, inline: true },
        { name: '🏆 Nivel de Corona', value: `${crownName} (Tier ${tier})`, inline: true },
        { name: '🍎 Manzanas Comidas', value: `${applesEaten}`, inline: true },
        { name: '✨ Recompensa', value: meta.perk, inline: true },
        { name: '🎯 Requisito Mínimo', value: `${meta.requirement} pts`, inline: true }
      ],
      footer: {
        text: `Snake Game Achievements • ID: ${meta.trophyId}`
      },
      timestamp: dateUnlocked
    }
  ]
};

// Generar mensaje formateado para Telegram / Slack
const telegramMessage = `👑 *¡NUEVA CORONA DESBLOQUEADA EN SNAKE GAME!* 🐍\n\n` +
  `👤 *Jugador:* ${playerName}\n` +
  `🏆 *Corona:* ${crownName} (Nivel ${tier})\n` +
  `⭐ *Puntuación:* ${score} pts\n` +
  `🍎 *Manzanas:* ${applesEaten}\n` +
  `✨ *Hito:* ${meta.perk}\n\n` +
  `🎮 ¡Supera el desafío en Snake Game!`;

return {
  json: {
    success: true,
    player: playerName,
    score: score,
    tier: tier,
    crownName: crownName,
    trophyId: meta.trophyId,
    dateUnlocked: dateUnlocked,
    meta: meta,
    discordPayload: discordEmbed,
    telegramPayload: {
      text: telegramMessage,
      parse_mode: 'Markdown'
    }
  }
};
